    }

    // -------------------------------------------------------------------------
    // Vegetation
    // -------------------------------------------------------------------------

    function makeCypress(x, z, scale = 1) {
      const tree = new THREE.Group();
      tree.position.set(x, terrainHeight(x, z), z);
      tree.scale.setScalar(scale);
      scene.add(tree);

      cylinder(
        0.16,
        0.24,
        2.3,
        materials.darkStone,
        0,
        1.15,
        0,
