        8
      );

      const levels = [
        { y: 1.7, radius: 1.55, height: 5.4 },
        { y: 3.35, radius: 1.25, height: 4.7 },
        { y: 4.7, radius: 0.9, height: 3.8 }
      ];

      for (const level of levels) {
        const foliage = new THREE.Mesh(
          new THREE.ConeGeometry(level.radius, level.height, 12),
