      foliage.scale.set(1.2, 0.75, 1);
      foliage.castShadow = true;
      bush.add(foliage);
    }

    [
      [-35, -27, 1.2], [-31, -31, 1.0], [-38, -18, 1.15],
      [-34, -9, 1.0], [-37, 7, 1.2], [-31, 19, 1.0],
      [-27, 24, 0.85], [33, -24, 1.15], [38, -13, 1.0],
      [36, 10, 1.2], [31, 23, 0.9], [18, 29, 0.8],
      [-15, 30, 0.85], [4, 31, 0.75], [-39, 27, 0.9]
    ].forEach(([x, z, scale]) => makeCypress(x, z, scale));

    [
      [-38, -7, 1.0], [-30, 15, 1.1], [35, -25, 1.1],
      [39, 7, 0.9], [-36, 27, 1.0], [18, 29, 1.0]
    ].forEach(([x, z, scale]) => makeOlive(x, z, scale));

    for (let i = 0; i < 34; i++) {
      const x = (Math.random() - 0.5) * 80;
      const z = (Math.random() - 0.5) * 65;

      if (
        Math.abs(x) < 15 && Math.abs(z) < 14 ||
        Math.abs(x + 23) < 6 && Math.abs(z + 2) < 11 ||
        Math.abs(x - 23) < 6 && Math.abs(z + 11) < 4
      ) {
        continue;
      }

      makeBush(x, z, 0.55 + Math.random() * 0.85);
    }

    // -------------------------------------------------------------------------
    // Statues, braziers, and small artifacts
    // -------------------------------------------------------------------------

    function makeStatue(x, z, rotation = 0, scale = 1) {
      const statue = new THREE.Group();
      statue.position.set(x, terrainHeight(x, z), z);
      statue.rotation.y = rotation;
      statue.scale.setScalar(scale);
      scene.add(statue);

      box(1.7, 0.55, 1.7, materials.darkStone, 0, 0.28, 0, statue);
      box(1.35, 0.38, 1.35, materials.stone, 0, 0.68, 0, statue);

      const torso = cylinder(
        0.32,
        0.48,
        1.15,
