      const leftArm = cylinder(
        0.12,
        0.16,
        1.15,
        materials.marble,
        -0.42,
        1.35,
        0,
        statue,
        8
      );
      leftArm.rotation.z = -0.35;

      const rightArm = cylinder(
        0.12,
        0.16,
        1.15,
        materials.marble,
        0.42,
        1.35,
        0,
        statue,
        8
      );
      rightArm.rotation.z = 0.35;

      box(0.16, 1.25, 0.16, materials.marble, 0.5, 0.92, 0, statue);
    }

    makeStatue(-6.2, 10.2, 0.25, 1.05);
    makeStatue(6.2, 10.2, -0.25, 0.95);
    makeStatue(-17.5, 11.5, 0.4, 0.85);
    makeStatue(18.5, 8.5, -0.35, 0.8);

    function makeBrazier(x, z) {
      const brazier = new THREE.Group();
      brazier.position.set(x, terrainHeight(x, z), z);
      scene.add(brazier);

      cylinder(0.72, 0.32, 0.48, materials.bronze, 0, 1.05, 0, brazier, 10);

      for (const angle of [0, Math.PI / 2, Math.PI, Math.PI * 1.5]) {
        const leg = box(
          0.12,
          0.9,
          0.12,
          materials.bronze,
          Math.cos(angle) * 0.48,
          0.45,
          Math.sin(angle) * 0.48,
