        );
        leg.rotation.z = Math.cos(angle) * 0.12;
        leg.rotation.x = Math.sin(angle) * 0.12;
      }

      const fire = new THREE.Mesh(
        new THREE.ConeGeometry(0.48, 0.85, 8),
        materials.fire
      );
      fire.position.y = 1.48;
      fire.castShadow = true;
      brazier.add(fire);

      const light = new THREE.PointLight(0xff641d, 2.2, 8, 2);
      light.position.y = 1.6;
      brazier.add(light);

      fires.push({ mesh: fire, light });
    }

    makeBrazier(10.5, 12.5);
    makeBrazier(-10.5, 12.5);
    makeBrazier(28, -5.5);

    // A red ceremonial cloth on the stoa.
    const banner = new THREE.Mesh(
      new THREE.PlaneGeometry(1.7, 3.2, 6, 8),
      materials.red
    );
    banner.position.set(3.9, 7.95, 7.7);
    banner.rotation.y = -0.12;
    banner.castShadow = true;
    stoa.add(banner);

    // -------------------------------------------------------------------------
    // Scattered ruins and stones
    // -------------------------------------------------------------------------

    const ruinMaterial = new THREE.MeshStandardMaterial({
      color: 0x918774,
      roughness: 1
    });

    for (let i = 0; i < 45; i++) {
      const x = (Math.random() - 0.5) * 78;
      const z = (Math.random() - 0.5) * 61;

      if (
        Math.abs(x) < 14 && Math.abs(z) < 15 ||
        Math.abs(x + 23) < 6 && Math.abs(z + 2) < 11 ||
        Math.abs(x - 23) < 6 && Math.abs(z + 11) < 4
      ) {
        continue;
      }

      const rock = new THREE.Mesh(
        new THREE.DodecahedronGeometry(
          0.25 + Math.random() * 0.8,
          0
        ),
        ruinMaterial
      );
      rock.position.set(
        x,
        terrainHeight(x, z) + 0.15,
        z
      );
      rock.scale.set(
        1 + Math.random(),
        0.45 + Math.random() * 0.8,
        1 + Math.random()
      );
      rock.rotation.set(
        Math.random() * 3,
        Math.random() * 3,
        Math.random() * 3
      );
      rock.castShadow = true;
      rock.receiveShadow = true;
      scene.add(rock);
    }

    // -------------------------------------------------------------------------
    // Custom orbit controls
    // -------------------------------------------------------------------------

    const orbit = {
      theta: 0.72,
      phi: 1.02,
      radius: 58,
      target: new THREE.Vector3(0, 4, 0)
    };

    const views = {
      overview: {
        theta: 0.72,
        phi: 1.02,
        radius: 58,
        target: [0, 4, 0]
      },
      temple: {
        theta: 0.48,
        phi: 1.04,
        radius: 31,
        target: [0, 5, 0]
      },
      gateway: {
        theta: 0.92,
        phi: 1.05,
        radius: 25,
        target: [23, 4, -11]
      },
      stoa: {
        theta: -0.72,
        phi: 1.04,
        radius: 27,
        target: [-23, 4, -2]
      }
    };

    let cameraGoal = null;
    const cameraOffset = new THREE.Vector3();
    const spherical = new THREE.Spherical();

    function applyCamera() {
      spherical.set(orbit.radius, orbit.phi, orbit.theta);
      cameraOffset.setFromSpherical(spherical);
      camera.position.copy(orbit.target).add(cameraOffset);
      camera.lookAt(orbit.target);
    }

    function setView(name) {
      const view = views[name];
      if (!view) return;

      cameraGoal = {
        theta: view.theta,
        phi: view.phi,
        radius: view.radius,
        target: new THREE.Vector3(...view.target)
      };

      document.querySelectorAll("[data-view]").forEach((button) => {
        button.classList.toggle("active", button.dataset.view === name);
      });
    }

    document.querySelectorAll("[data-view]").forEach((button) => {
      button.addEventListener("click", () => {
        setView(button.dataset.view);
      });
    });

    const pointers = new Map();
    let lastX = 0;
    let lastY = 0;
    let dragging = false;
    let pinchDistance = 0;

    const canvas = renderer.domElement;

    canvas.addEventListener("pointerdown", (event) => {
      canvas.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });

      if (pointers.size === 1) {
        dragging = true;
        lastX = event.clientX;
        lastY = event.clientY;
      } else if (pointers.size === 2) {
        const points = [...pointers.values()];
        pinchDistance = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );
      }

      cameraGoal = null;
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!pointers.has(event.pointerId)) return;

      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 1 && dragging) {
        const deltaX = event.clientX - lastX;
        const deltaY = event.clientY - lastY;

        orbit.theta -= deltaX * 0.005;
        orbit.phi = THREE.MathUtils.clamp(
          orbit.phi - deltaY * 0.005,
          0.24,
          1.43
        );

        lastX = event.clientX;
        lastY = event.clientY;
      } else if (pointers.size === 2) {
        const points = [...pointers.values()];
        const nextDistance = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );

        if (pinchDistance > 0 && nextDistance > 0) {
          orbit.radius = THREE.MathUtils.clamp(
            orbit.radius * (pinchDistance / nextDistance),
            15,
            105
          );
        }

        pinchDistance = nextDistance;
      }
    });

    function endPointer(event) {
      pointers.delete(event.pointerId);

      if (pointers.size === 0) {
        dragging = false;
        pinchDistance = 0;
      } else {
        const remaining = [...pointers.values()][0];
        lastX = remaining.x;
        lastY = remaining.y;
      }
    }

    canvas.addEventListener("pointerup", endPointer);
    canvas.addEventListener("pointercancel", endPointer);
    canvas.addEventListener("lostpointercapture", endPointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        cameraGoal = null;
        orbit.radius = THREE.MathUtils.clamp(
          orbit.radius * Math.exp(event.deltaY * 0.001),
          15,
          105
        );
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", () => setView("overview"));
    canvas.addEventListener("contextmenu", (event) => event.preventDefault());

    window.addEventListener("keydown", (event) => {
      cameraGoal = null;

      switch (event.key) {
        case "ArrowLeft":
          orbit.theta += 0.08;
          break;
        case "ArrowRight":
          orbit.theta -= 0.08;
          break;
        case "ArrowUp":
          orbit.phi = Math.max(0.24, orbit.phi - 0.06);
          break;
        case "ArrowDown":
          orbit.phi = Math.min(1.43, orbit.phi + 0.06);
          break;
        case "+":
        case "=":
          orbit.radius = Math.max(15, orbit.radius * 0.9);
          break;
        case "-":
          orbit.radius = Math.min(105, orbit.radius * 1.1);
          break;
        case "r":
        case "R":
          setView("overview");
          break;
      }
    });

    // -------------------------------------------------------------------------
    // Resize and animation
    // -------------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    const clock = new THREE.Clock();
    let firstFrame = true;

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);

      if (cameraGoal) {
        const easing = 1 - Math.exp(-delta * 3.4);

        orbit.theta = THREE.MathUtils.lerp(
          orbit.theta,
          cameraGoal.theta,
          easing
        );
        orbit.phi = THREE.MathUtils.lerp(
          orbit.phi,
          cameraGoal.phi,
          easing
        );
        orbit.radius = THREE.MathUtils.lerp(
          orbit.radius,
          cameraGoal.radius,
          easing
        );
        orbit.target.lerp(cameraGoal.target, easing);

        if (
          Math.abs(orbit.theta - cameraGoal.theta) < 0.001 &&
          Math.abs(orbit.phi - cameraGoal.phi) < 0.001 &&
          Math.abs(orbit.radius - cameraGoal.radius) < 0.01 &&
          orbit.target.distanceTo(cameraGoal.target) < 0.01
        ) {
          cameraGoal = null;
        }
      }

      for (const item of fires) {
        const pulse = 1.25 + Math.sin(clock.elapsedTime * 8.5) * 0.25;
        item.mesh.scale.set(
          0.9 + pulse * 0.12,
          pulse,
          0.9 + pulse * 0.12
        );
        item.light.intensity = 1.8 + pulse * 1.2;
      }

      applyCamera();
      renderer.render(scene, camera);

      if (firstFrame) {
        firstFrame = false;
        loading.classList.add("hidden");
        setTimeout(() => loading.remove(), 700);
      }
    }

    applyCamera();
    renderer.setAnimationLoop(animate);
  </script>
